async function main(): Promise<void> {
  const f: any = (x: number) => x;
  let name = "none";
  let ok = false;
  try { structuredClone(f); } catch (e: any) { name = e.name; ok = e.message.endsWith("could not be cloned."); }
  console.log(name, ok);
  let inner = "none";
  try { structuredClone({ f }); } catch (e: any) { inner = e.name; }
  console.log(inner);
}
